class TaskBinding{static Object value(double r,double i){return new alternate.Complex(r,i);}static double[]parts(Object x){return new double[]{((alternate.Complex)x).real(),((alternate.Complex)x).imaginary()};}static Object operation(Object a,Object b,int op){alternate.Complex x=(alternate.Complex)a,y=(alternate.Complex)b;return switch(op){case 0->x.add(y);case 1->x.subtract(y);case 2->x.multiply(y);default->x.divide(y);};}static Object[]array(Object...a){return java.util.Arrays.copyOf(a,a.length,alternate.Complex[].class);}static Object sum(Object[]a){return alternate.Complex.sum((alternate.Complex[])a);}static Object product(Object[]a){return alternate.Complex.product((alternate.Complex[])a);}}
